import * as React from "react"
import { Link, PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import SubNavigation from "../components/subnav";


const userData: UserProfile = data;

const IndustryPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconFill="fill-Tofu"
      footerLogoFill="fill-Tofu"
      bgImage={images.bgIndustry.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <SubNavigation />
        <section className={styles.container}>
            <section className={styles.section} id={data.submenu[0]}>
                <div className="flex flex-col">
                    <h1 className="head-1" dangerouslySetInnerHTML={{ __html: t("industry.title") ?? "" }} />
                    <p className="body-1">{t("industry.paragraph1")}</p>
                    <a className="px-8 py-4 border-2 border-Tofu hover:bg-Tofu hover:text-DarkSea" href="/contact-us">{t("industry.cta")}</a>
                </div>
            </section>
            <section className={styles.section} id={data.submenu[1]}>  
                <div className="bg-[pink] h-48"></div>
            </section>
            <section className={styles.section} id={data.submenu[2]}>  
                <div className="bg-[red] h-48"></div>
            </section>
            <section className={styles.section} id={data.submenu[3]}>  
                <div className="bg-[blue] h-48"></div>
            </section>
            <section className={styles.section} id={data.submenu[4]}>  
                <div className="bg-[green] h-48"></div>
            </section>
            <section className={styles.section} id={data.submenu[5]}>  
                <div className="bg-[brown] h-48"></div>
            </section>
            <section className={styles.section} id={data.submenu[6]}>  
                <div className="bg-[cyan] h-48"></div>
            </section>
        </section>

    </Layout>
  )
}

export default IndustryPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16 text-Tofu mt-[422px]",
  section: "flex flex-col sm:flex-row w-full",
  title: "text-center mt-[70%] relative z-40",
}